  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderId : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

class ProductAvailability {
}

Manufacturer "1" -- "0..*" Product : manufactures
Product "0..*" -- "0..*" Country : available in
Product "1" -- "0..*" Order : refers to
Representative "1" -- "1" Country : responsible for
Representative "1" -- "0..*" Order : places
Customer "1" -- "0..*" Order : places
Customer "0..*" -- "0..*" Country : resells in
Product "0..*" -- "1" Order : is part of

@enduml

